const driveData = $('Google Drive Yükle').first().json;
const emailData = $('Gmail Trigger').first().json;
const geminiRaw = $('Gemini AI Beleg-OCR').first().json;

let raw = '';
if (geminiRaw.choices && geminiRaw.choices[0] && geminiRaw.choices[0].message) {
  raw = geminiRaw.choices[0].message.content || '';
} else if (geminiRaw.content && geminiRaw.content.parts && geminiRaw.content.parts[0]) {
  raw = geminiRaw.content.parts[0].text || '';
} else if (geminiRaw.text) {
  raw = geminiRaw.text;
} else if (typeof geminiRaw === 'string') {
  raw = geminiRaw;
} else {
  raw = JSON.stringify(geminiRaw);
}

let jsonStr = String(raw)
  .replace(/^\`\`\`(?:json)?\s*/i, '')
  .replace(/\`\`\`\s*$/, '')
  .trim();

let aiData = {};
try {
  aiData = JSON.parse(jsonStr);
} catch (e) {
  const m = jsonStr.match(/\{[\s\S]*\}/);
  if (m) {
    try { aiData = JSON.parse(m[0]); } catch (e2) { aiData = {}; }
  }
}

const origCurrency = (aiData.currency || 'EUR').toUpperCase();
const origGross = parseFloat(aiData.gross_amount) || 0;
let exchangeRate = 1.0;
let grossEur = origGross;

// Wenn Beleg bereits in EUR ist, gilt EXAKT der Rechnungsbetrag ohne Umrechnung!
if (origCurrency !== 'EUR' && origCurrency === 'USD') {
  // Nur falls kein EUR-Betrag im Beleg existiert
  exchangeRate = 1.08;
  grossEur = Math.round((origGross / exchangeRate) * 100) / 100;
} else {
  exchangeRate = 1.0000;
  grossEur = origGross;
}

let invoiceVatRate = parseFloat(aiData.invoice_vat_rate);
if (isNaN(invoiceVatRate)) invoiceVatRate = (grossEur > 0 ? 19 : 0);
let netEur = parseFloat(aiData.net_amount);
if (isNaN(netEur) || netEur <= 0) {
  netEur = grossEur;
}
let invoiceVatAmount = parseFloat(aiData.invoice_vat_amount);

const isRc = Boolean(aiData.reverse_charge);
let rcTaxRate = 19.00;
let rcTaxAmount = 0.00;
let rcInputVatAmount = 0.00;

if (isRc) {
  invoiceVatRate = 0;
  invoiceVatAmount = 0;
  netEur = grossEur;
  rcTaxAmount = Math.round(netEur * 0.19 * 100) / 100;
  rcInputVatAmount = rcTaxAmount;
} else {
  if (isNaN(netEur) || netEur <= 0) {
    netEur = invoiceVatRate > 0 ? (grossEur / (1 + (invoiceVatRate / 100))) : grossEur;
  }
  if (isNaN(invoiceVatAmount)) {
    invoiceVatAmount = grossEur - netEur;
  }
}

const sender = emailData.from?.text || emailData.from?.value?.[0]?.address || emailData.from?.name || 'Unbekannt';
const vendor = aiData.vendor_name || emailData.from?.value?.[0]?.name || emailData.from?.name || 'Unbekannter Lieferant';
const rawEmailText = `${emailData.subject || ''} ${emailData.text || ''} ${emailData.snippet || ''}`.toLowerCase();

// Subscription heuristic
let isRecurring = Boolean(aiData.is_recurring);
let recurringInterval = aiData.recurring_interval || (isRecurring ? 'monthly' : 'none');
if (!isRecurring && /subscription|abo|monthly|recurring|wiederkehrend|erneuerung|monatlich/i.test(rawEmailText)) {
  isRecurring = true;
  recurringInterval = 'monthly';
}

// Funding Source, Capital Movement & Safety Rules (Rule 2)
let fundingSource = aiData.funding_source || 'business_account';
let isDeductible = aiData.is_deductible !== false;
let taxCategory = aiData.tax_category || 'software_cloud';
let econClass = 'business_expense';
let econPurpose = 'business';
let capitalMovement = 'none';
let dedPct = parseFloat(aiData.deductible_percentage) || 100;
const reviewCodes = [];

if (fundingSource === 'melih_private' || /melih.*privat/i.test(rawEmailText)) {
  if (taxCategory === 'private_expense' || /privat.*melih|persönlich/i.test(rawEmailText)) {
    fundingSource = 'melih_private';
    isDeductible = false;
    taxCategory = 'private_expense';
    econClass = 'private_expense';
    econPurpose = 'private';
    capitalMovement = 'none';
    dedPct = 0;
  } else {
    // RULE 2: Melih bezahlt Betriebsausgabe -> Sicherheitsbremse (needs_review)
    fundingSource = 'melih_private';
    econPurpose = 'business';
    econClass = 'business_expense';
    isDeductible = true;
    capitalMovement = 'none';
    reviewCodes.push('MELIH_BUSINESS_PAYMENT_NEEDS_REVIEW');
  }
} else if (fundingSource === 'kemal_private' || /kemal.*privat|privatkonto/i.test(rawEmailText)) {
  fundingSource = 'kemal_private';
  econClass = 'business_expense';
  econPurpose = 'business';
  capitalMovement = 'private_contribution'; // Privateinlage
  isDeductible = true;
}

if (taxCategory === 'business_meals') {
  dedPct = 70;
}

// Cash-basis dates per § 11 EStG
const invoiceDate = aiData.invoice_date || new Date().toISOString().slice(0, 10);
const paymentDate = aiData.payment_date || invoiceDate;

// GoBD File Hash
const hashInput = `${vendor}_${invoiceDate}_${grossEur}_${driveData.id || ''}`;
let hashVal = 0;
for (let i = 0; i < hashInput.length; i++) {
  hashVal = ((hashVal << 5) - hashVal) + hashInput.charCodeAt(i);
  hashVal |= 0;
}
const simulatedHash = 'sha256_' + Math.abs(hashVal).toString(16).padStart(12, '0');

// Safety Rules (Rule 1 & Rule 3)
if (isRc && !aiData.vendor_vat_id && aiData.vendor_country === 'IE') {
  reviewCodes.push('VAT_ID_MISSING');
}
if (!aiData.payment_date) {
  reviewCodes.push('PAYMENT_MISSING');
}
if (grossEur <= 0 || grossEur > 5000) {
  reviewCodes.push('OCR_LOW_CONFIDENCE');
}

const needsReview = Boolean(aiData.needs_manual_review || reviewCodes.length > 0);

return [{
  json: {
    document_id: 'DOC-' + Date.now(),
    document_type: aiData.document_type || 'invoice',
    original_filename: driveData.name || 'Beleg.pdf',
    original_file_hash: simulatedHash,
    invoice_date: invoiceDate,
    service_date: aiData.service_date || null,
    due_date: aiData.due_date || null,
    payment_date: paymentDate,
    cash_flow_date: paymentDate,
    tax_year: (paymentDate || invoiceDate).slice(0, 4),
    vendor_name: vendor,
    vendor_country: (aiData.vendor_country || 'DE').toUpperCase(),
    vendor_vat_id: aiData.vendor_vat_id || null,
    invoice_number: aiData.invoice_number || null,
    description: aiData.description_summary || emailData.subject || null,
    currency: 'EUR',
    original_amount: origGross,
    original_currency: origCurrency,
    exchange_rate: exchangeRate,
    gross_amount: Math.round(grossEur * 100) / 100,
    net_amount: Math.round(netEur * 100) / 100,
    vat_rate: isRc ? 0 : invoiceVatRate,
    vat_amount: isRc ? 0 : Math.round(invoiceVatAmount * 100) / 100,
    invoice_vat_rate: invoiceVatRate,
    invoice_vat_amount: Math.round(invoiceVatAmount * 100) / 100,
    reverse_charge: isRc,
    reverse_charge_tax_rate: rcTaxRate,
    reverse_charge_tax_amount: rcTaxAmount,
    reverse_charge_input_vat_amount: rcInputVatAmount,
    reverse_charge_reason: isRc ? (aiData.reverse_charge_reason || '§ 13b UStG / B2B Ausland') : null,
    input_vat_eligible: !isRc && isDeductible,
    tax_category: taxCategory,
    euer_category: taxCategory,
    euer_mapping_version: '2026',
    tax_form_year: (paymentDate || invoiceDate).slice(0, 4),
    funding_source: fundingSource,
    payer_type: fundingSource,
    paid_by: fundingSource === 'melih_private' ? 'melih' : 'kemal',
    economic_purpose: econPurpose,
    capital_movement: capitalMovement,
    economic_classification: econClass,
    is_deductible: isDeductible,
    deductible_percentage: dedPct,
    deductibility_reason: aiData.deductibility_reason || (dedPct === 70 ? '70% Bewirtung per § 4 Abs. 5 EStG' : null),
    is_recurring: isRecurring,
    recurring_interval: recurringInterval,
    payment_method: aiData.payment_method || 'bank_transfer',
    drive_file_id: driveData.id || null,
    drive_web_view_link: driveData.webViewLink || null,
    email_sender: typeof sender === 'object' ? JSON.stringify(sender) : String(sender),
    email_subject: emailData.subject || null,
    raw_ai_extraction: aiData,
    record_mode: 'production',
    needs_review: needsReview,
    review_codes: reviewCodes,
    status: needsReview ? 'review_needed' : 'processed'
  }
}];
